        unseen.remove(start)
        obj = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                q = (r + dr, c + dc)
                if q in unseen:
                    unseen.remove(q)
                    obj.add(q)
                    stack.append(q)
        objects.append(obj)

    def has_marker(obj):
        return any(grid[r][c] == 7 for r, c in obj)

    marked = [obj for obj in objects if has_marker(obj)]
    if len(marked) < 2:
        # Orange/background-only separator rows are removed.
        return [[4 if x == 7 else x for x in row]
                for row in grid if any(x == 4 for x in row)]

    # The upper-left marked object stays fixed.  The other object is moved
    # so that the yellow cell adjoining its marker covers the fixed marker.
    marked.sort(key=lambda obj: (min(r for r, c in obj),
                                 min(c for r, c in obj)))
    fixed, moving = marked[0], marked[1]
    target = min((r, c) for r, c in fixed if grid[r][c] == 7)
    moving_marks = {(r, c) for r, c in moving if grid[r][c] == 7}
    adjoining = []
    for r, c in moving:
        if grid[r][c] == 4 and any((r + dr, c + dc) in moving_marks
                                   for dr, dc in ((1, 0), (-1, 0),
                                                  (0, 1), (0, -1))):
            adjoining.append((r, c))
    source = min(adjoining)
    dr, dc = target[0] - source[0], target[1] - source[1]

    yellow = set()
    for obj in objects:
        if obj is moving:
            continue
        for r, c in obj:
            if grid[r][c] == 4:
                yellow.add((r, c))
    for r, c in moving:
        if grid[r][c] == 4:
            yellow.add((r + dr, c + dc))

