    r1 = max(r for r, c in yellow)
    c0 = min(c for r, c in yellow)
    c1 = max(c for r, c in yellow)
    return [[4 if (r, c) in yellow else 1
             for c in range(c0, c1 + 1)]
            for r in range(r0, r1 + 1)]
